create table cicd_dev.demo_tasks (
    task_id    number generated by default as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by 1 cache 20 noorder
    nocycle nokeep noscale not null enable,
    task_name  varchar2(200 byte) not null enable,
    status     varchar2(20 byte) default 'OPEN' not null enable,
    created_at timestamp(6) default systimestamp not null enable,
    priority   varchar2(10 byte) default 'MEDIUM' not null enable
);

alter table cicd_dev.demo_tasks
    add constraint chk_demo_tasks_status
        check ( status in ( 'OPEN', 'IN_PROGRESS', 'DONE' ) ) enable;

alter table cicd_dev.demo_tasks add primary key ( task_id )
    using index enable;


